<?php $title='Subscribers';require __DIR__.'/_layout.php';if(!can_manage('subscribers'))exit('Forbidden');$rows=db()->query("SELECT * FROM subscribers ORDER BY subscribed_at DESC")->fetchAll();?><h1>Subscribers</h1><table class="table"><tr><th>Email</th><th>Status</th><th>Subscribed</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['email'])?></td><td><?=e($r['status'])?></td><td><?=e($r['subscribed_at'])?></td></tr><?php endforeach;?></table><?php require __DIR__.'/_footer.php';?>